  --learner-prose-geometry: 0;
  --learner-control-geometry: 0;
  --learner-heading-geometry: 32;
  --learner-reading-measure: 72ch;
  font-family: var(--learner-font-family);
  font-variation-settings: "GEOM" var(--learner-prose-geometry);
}

.learner-course-shell :is(h1, h2, h3, h4, h5, h6) {
  font-family: var(--learner-font-family);
  font-variation-settings: "GEOM" var(--learner-heading-geometry);
}

.learner-course-shell :is(button, input, textarea, select, [data-slot="button"]) {
  font-family: var(--learner-font-family);
  font-variation-settings: "GEOM" var(--learner-control-geometry);
}

.learner-reader-with-shell .content-editor[data-mode="reader"] .content-prose {
  font-family: var(--learner-font-family);
  font-variation-settings: "GEOM" var(--learner-prose-geometry);
}

